// Shared in-memory data layer used by BOTH entry points (server.js and cli.js).
// Claude should spot this as the core module when explaining the codebase.

const items = new Map([
  ['SKU-100', { sku: 'SKU-100', name: 'USB-C cable', qty: 40 }],
  ['SKU-200', { sku: 'SKU-200', name: 'Laptop stand', qty: 12 }],
  ['SKU-300', { sku: 'SKU-300', name: 'Wireless mouse', qty: 0 }]
]);

// Return all items as an array.
export function listItems() {
  return [...items.values()];
}

// Return one item or undefined.
export function getItem(sku) {
  return items.get(sku);
}

// Change stock by a positive or negative amount. Stock never goes below 0.
export function adjustStock(sku, delta) {
  const item = items.get(sku);
  if (!item) throw new Error(`Unknown SKU: ${sku}`);
  if (!Number.isInteger(delta)) throw new Error('delta must be an integer');
  item.qty = Math.max(0, item.qty + delta);
  return item;
}

// Items with zero stock.
export function outOfStock() {
  return listItems().filter((i) => i.qty === 0);
}

// ENTRY POINT 1: HTTP API. Started with `npm start`.
import http from 'node:http';
import { listItems, getItem, adjustStock, outOfStock } from './store.js';

const PORT = Number(process.env.PORT) || 3000; // configurable via PORT env var

function send(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(body));
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);
  const parts = url.pathname.split('/').filter(Boolean); // e.g. ['items','SKU-100']

  if (req.method === 'GET' && url.pathname === '/health') {
    return send(res, 200, { status: 'ok' });
  }
  if (req.method === 'GET' && url.pathname === '/items') {
    return send(res, 200, listItems());
  }
  if (req.method === 'GET' && url.pathname === '/items/out-of-stock') {
    return send(res, 200, outOfStock());
  }
  if (req.method === 'GET' && parts[0] === 'items' && parts.length === 2) {
    const item = getItem(parts[1]);
    return item ? send(res, 200, item) : send(res, 404, { error: 'not found' });
  }
  // POST /items/:sku/adjust?delta=5 changes stock
  if (req.method === 'POST' && parts[0] === 'items' && parts[2] === 'adjust') {
    try {
      const delta = Number(url.searchParams.get('delta'));
      return send(res, 200, adjustStock(parts[1], delta));
    } catch (err) {
      return send(res, 400, { error: err.message });
    }
  }
  send(res, 404, { error: 'route not found' });
});

server.listen(PORT, () => {
  console.log(`inventory API listening on http://localhost:${PORT}`);
});

