// ENTRY POINT 2: command-line tool. Run `npm run cli -- <command>`
// or, after `npm link`, the `inventory` bin declared in package.json.
import { listItems, getItem, adjustStock, outOfStock } from './store.js';

const [command, ...args] = process.argv.slice(2);

function printTable(rows) {
  for (const r of rows) console.log(`${r.sku}\t${r.qty}\t${r.name}`);
}

switch (command) {
  case 'list':
    printTable(listItems());
    break;
  case 'show': {
    const item = getItem(args[0]);
    if (!item) {
      console.error(`Not found: ${args[0]}`);
      process.exit(1);
    }
    printTable([item]);
    break;
  }
  case 'adjust': // e.g. adjust SKU-100 -5
    try {
      printTable([adjustStock(args[0], Number(args[1]))]);
    } catch (err) {
      console.error(err.message);
      process.exit(1);
    }
    break;
  case 'empty':
    printTable(outOfStock());
    break;
  default:
    console.log('Usage: inventory <list | show SKU | adjust SKU DELTA | empty>');
    process.exit(command ? 1 : 0);
}

