"""Split a GST amount into CGST/SGST or IGST."""

from decimal import ROUND_HALF_UP, Decimal

ZERO = Decimal("0.00")


def _round(value: Decimal) -> Decimal:
    # Single rounding point; CLAUDE.md marks this as do-not-touch.
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def split_tax(amount: Decimal, rate_percent: Decimal, intra_state: bool) -> dict[str, Decimal]:
    """Return tax heads for a taxable amount.

    intra_state=True  -> CGST + SGST (tax shared equally)
    intra_state=False -> IGST (full tax)
    The rate is passed in; take current rates from official GST notifications.
    """
    if amount < 0:
        raise ValueError("amount must not be negative")
    if not Decimal("0") <= rate_percent <= Decimal("100"):
        raise ValueError("rate_percent must be between 0 and 100")

    tax = _round(amount * rate_percent / Decimal("100"))
    if intra_state:
        cgst = _round(tax / 2)
        sgst = tax - cgst  # remainder keeps cgst + sgst == tax exactly
        return {"cgst": cgst, "sgst": sgst, "igst": ZERO}
    return {"cgst": ZERO, "sgst": ZERO, "igst": tax}


def invoice_total(amount: Decimal, rate_percent: Decimal, intra_state: bool) -> Decimal:
    """Taxable amount plus all tax heads."""
    heads = split_tax(amount, rate_percent, intra_state)
    return _round(amount) + sum(heads.values(), ZERO)

from decimal import Decimal

import pytest

from invoice_calc.gst import invoice_total, split_tax


def test_intra_state_splits_equally():
    heads = split_tax(Decimal("1000"), Decimal("18"), intra_state=True)
    assert heads == {"cgst": Decimal("90.00"), "sgst": Decimal("90.00"), "igst": Decimal("0.00")}


def test_inter_state_uses_igst():
    heads = split_tax(Decimal("1000"), Decimal("18"), intra_state=False)
    assert heads["igst"] == Decimal("180.00")
    assert heads["cgst"] == heads["sgst"] == Decimal("0.00")


def test_odd_paise_still_adds_up():
    # 0.05 tax cannot split evenly; the halves must still sum to the total
    heads = split_tax(Decimal("1.00"), Decimal("5"), intra_state=True)
    assert heads["cgst"] + heads["sgst"] == Decimal("0.05")


def test_invoice_total():
    assert invoice_total(Decimal("500"), Decimal("5"), intra_state=False) == Decimal("525.00")


def test_negative_amount_rejected():
    with pytest.raises(ValueError):
        split_tax(Decimal("-1"), Decimal("18"), intra_state=True)


def test_bad_rate_rejected():
    with pytest.raises(ValueError):
        split_tax(Decimal("100"), Decimal("150"), intra_state=True)

