  assert.throws(() => applyDiscount(49999, 'FLAT100'), /minimum order/);
});

test('codes are case-insensitive and trimmed', () => {
  assert.equal(applyDiscount(10000, '  save10 '), 9000);
});

test('empty or missing code returns subtotal', () => {
  assert.equal(applyDiscount(10000, ''), 10000);
  assert.equal(applyDiscount(10000), 10000);
});

test('unknown code throws a clear error', () => {
  assert.throws(() => applyDiscount(10000, 'FREE'), /Unknown discount code: FREE/);
});

// Cart helpers. All amounts are integer paise (see CLAUDE.md).

export function subtotal(items) {
  return items.reduce((sum, { price, qty }) => sum + price * qty, 0);
}

// Added in step 3 from docs/PLAN.md. Each rule returns the discount in paise.
const DISCOUNTS = {
  SAVE10: (amount) => Math.floor(amount / 10), // 10%, rounded down
  FLAT100: (amount) => {
    if (amount < 50000) {
      throw new Error('FLAT100 needs a minimum order of 50000 paise');
    }
    return 10000;
  },
};

export function applyDiscount(subtotalPaise, code = '') {
  const key = String(code).trim().toUpperCase();
  if (key === '') return subtotalPaise; // no code: unchanged

  const rule = DISCOUNTS[key];
  if (!rule) throw new Error(`Unknown discount code: ${key}`);

  return Math.max(0, subtotalPaise - rule(subtotalPaise)); // never negative
}

