#!/usr/bin/env node
// PostToolUse hook: runs Prettier on the file Claude just edited.
// Claude Code sends the hook input as JSON on stdin.
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import path from 'node:path';

let raw = '';
for await (const chunk of process.stdin) raw += chunk;

const input = JSON.parse(raw || '{}');
// For Edit, MultiEdit and Write the target is tool_input.file_path
const filePath = input.tool_input?.file_path;
if (!filePath || !existsSync(filePath)) process.exit(0); // nothing to format

const projectDir = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
// Use the repo's own Prettier so every teammate gets the same version
const prettierBin = path.join(projectDir, 'node_modules', 'prettier', 'bin', 'prettier.cjs');
if (!existsSync(prettierBin)) {
  console.error('Prettier not installed. Run npm install.');
  process.exit(1); // non-blocking error: shown to the user, Claude continues
}

// --ignore-unknown skips files Prettier cannot parse (e.g. .sh, .txt)
const result = spawnSync(
  process.execPath,
  [prettierBin, '--write', '--ignore-unknown', filePath],
  { cwd: projectDir, encoding: 'utf8' }
);

if (result.status !== 0) {
  // Exit 2 in PostToolUse: the edit already happened, but stderr goes
  // back to Claude so it can fix the syntax error Prettier found
  console.error(`Prettier failed on ${filePath}:\n${result.stderr}`);
  process.exit(2);
}

process.exit(0); // success: formatted silently

#!/usr/bin/env node
// PreToolUse hook: blocks edits to protected files BEFORE the tool runs.
import path from 'node:path';

let raw = '';
for await (const chunk of process.stdin) raw += chunk;

const input = JSON.parse(raw || '{}');
const filePath = input.tool_input?.file_path;
if (!filePath) process.exit(0);

const projectDir = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
const rel = path.relative(projectDir, path.resolve(filePath)).split(path.sep).join('/');

// Files no one (human or agent) should change through Claude
const protectedRules = [
  (p) => p === '.env' || p.startsWith('.env.'), // secrets
  (p) => p === 'package-lock.json',             // change only via npm
  (p) => p.startsWith('.git/'),                 // git internals
  (p) => p.startsWith('.claude/hooks/'),        // hooks cannot rewrite themselves
];

if (protectedRules.some((rule) => rule(rel))) {
  // Exit code 2 = block the tool call. stderr is sent to Claude as the reason.
  console.error(
    `Blocked: ${rel} is a protected file (${input.tool_name}). ` +
      'Ask the user to change it manually if it is really needed.'
  );
  process.exit(2);
}

process.exit(0); // allow the edit

