"""shop-db: a read-only MCP server over SQLite. Transport: stdio."""
import os
import sqlite3
import sys
from contextlib import closing
from pathlib import Path

from mcp.server.fastmcp import FastMCP

HERE = Path(__file__).parent
DB_PATH = Path(os.environ.get("SHOP_DB_PATH", "shop.db"))  # value set in .mcp.json env
if not DB_PATH.is_absolute():
    DB_PATH = HERE / DB_PATH  # resolve against this file, not Claude's working dir

MAX_ROWS = 200
mcp = FastMCP("shop-db")  # server name shown in the /mcp panel


def connect() -> sqlite3.Connection:
    # mode=ro: SQLite refuses every write, even if a bad query gets past our check
    return sqlite3.connect(f"file:{DB_PATH}?mode=ro", uri=True)


# TOOL: an action the model decides to call. Claude Code asks you before running it.
@mcp.tool()
def list_tables() -> list[str]:
    """List the table names in the shop database."""
    with closing(connect()) as conn:
        rows = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
        ).fetchall()
    return [r[0] for r in rows]


@mcp.tool()
def run_select(sql: str) -> dict:
    """Run ONE read-only SELECT (or WITH ... SELECT) query. Returns up to 200 rows."""
    if not sql.lstrip().lower().startswith(("select", "with")):
        raise ValueError("Only SELECT/WITH queries are allowed.")  # sent back to Claude as a tool error
    with closing(connect()) as conn:
        cur = conn.execute(sql)  # execute() rejects multiple statements
        cols = [c[0] for c in cur.description]
        rows = cur.fetchmany(MAX_ROWS)  # cap the output so it does not flood the context
    return {"columns": cols, "rows": [list(r) for r in rows],
            "truncated": len(rows) == MAX_ROWS}


# RESOURCE: read-only data the user attaches with @shop-db:schema://shop
@mcp.resource("schema://shop")
def schema() -> str:
    """CREATE TABLE statements for every table."""
    with closing(connect()) as conn:
        rows = conn.execute("SELECT sql FROM sqlite_master WHERE type='table'").fetchall()
    return "\n\n".join(r[0] for r in rows)


# PROMPT: a reusable template, run as /mcp__shop-db__sales_report 2026-01
@mcp.prompt()
def sales_report(month: str) -> str:
    """Monthly sales summary. month format: YYYY-MM."""
    return (f"Using the shop-db tools, report total revenue, order count and the "
            f"top customer for {month}. Show the SQL you ran.")


if __name__ == "__main__":
    print(f"shop-db reading {DB_PATH}", file=sys.stderr)  # stdout is reserved for JSON-RPC
    mcp.run()  # default transport is stdio

{
  "mcpServers": {
