// Code under review. The subagent reads this; it can never change it.

/**
 * Apply a percentage discount to a price in rupees.
 * @param {number} price - original price, must be >= 0
 * @param {number} percent - discount between 0 and 100
 * @returns {number} discounted price rounded to 2 decimals
 */
function applyDiscount(price, percent) {
  if (typeof price !== 'number' || price < 0) {
    throw new RangeError('price must be a non-negative number');
  }
  if (typeof percent !== 'number' || percent < 0 || percent > 100) {
    throw new RangeError('percent must be between 0 and 100');
  }
  const result = price * (1 - percent / 100);
  return Math.round(result * 100) / 100;
}

/**
 * Pick the best coupon (highest percent) from a list.
 * @param {{code: string, percent: number}[]} coupons
 */
function bestCoupon(coupons) {
  if (!Array.isArray(coupons) || coupons.length === 0) return null;
  return coupons.reduce((best, c) => (c.percent > best.percent ? c : best));
}

module.exports = { applyDiscount, bestCoupon };

// Built-in Node test runner: run with `npm test` (Node 18+).
const test = require('node:test');
const assert = require('node:assert/strict');
const { applyDiscount, bestCoupon } = require('../src/discount');

test('applies a 10% discount', () => {
  assert.equal(applyDiscount(500, 10), 450);
});

test('rounds to 2 decimals', () => {
  assert.equal(applyDiscount(99.99, 15), 84.99);
});

test('rejects percent above 100', () => {
  assert.throws(() => applyDiscount(100, 120), RangeError);
