// The same review, built on the Claude Agent SDK. It uses the same agent loop as Claude Code.
// Run: npm run review:sdk -- main
import { execSync } from "node:child_process";
import { query } from "@anthropic-ai/claude-agent-sdk";

const base = process.argv[2] ?? "main";
const diff = execSync(`git diff ${base}...HEAD`, { encoding: "utf8" });

if (!diff.trim()) {
  console.log(`No changes against ${base}`);
  process.exit(0);
}

const run = query({
  prompt: `Review this diff using the rules in CLAUDE.md. List issues as: severity, file:line, fix.\n\n${diff}`,
  options: {
    // By default the SDK uses a minimal system prompt. Opt in to the Claude Code one.
    systemPrompt: { type: "preset", preset: "claude_code" },
    // By default the SDK loads no settings files. 'project' loads CLAUDE.md and .claude/settings.json.
    settingSources: ["project"],
    allowedTools: ["Read", "Grep", "Glob"], // read-only reviewer
    permissionMode: "default",            // tools outside the allowlist are not auto-approved
    maxTurns: 8,                            // cost guard
  },
});

// query() streams messages. The final message has type 'result'.
for await (const message of run) {
  if (message.type === "system" && message.subtype === "init") {
    console.error(`session ${message.session_id} model ${message.model}`);
  }
  if (message.type === "result") {
    if (message.subtype === "success") {
      console.log(message.result);
    } else {
      console.error(`Run ended early: ${message.subtype}`); // e.g. error_max_turns
    }
    console.error(`turns=${message.num_turns} cost=$${message.total_cost_usd.toFixed(4)}`);
  }
}

