#!/usr/bin/env node
// PreToolUse hook: Claude Code sends the pending tool call as JSON on stdin.
// Exit code 0 lets the tool run.
// Exit code 2 blocks the call, and stderr is shown to Claude as the reason.

let raw = "";
process.stdin.on("data", (chunk) => (raw += chunk));

process.stdin.on("end", () => {
  let input;
  try {
    input = JSON.parse(raw);
  } catch {
    process.exit(0); // never break the session on bad input
  }

  const tool = input.tool_name; // e.g. "Read", "Edit", "Write"
  const filePath = (input.tool_input && input.tool_input.file_path) || "";

  // Block secrets files: .env, .env.local, .env.production and similar
  const isSecret = /(^|[\\/])\.env(\.|$)/.test(filePath);

  if (isSecret) {
    console.error(
      `Blocked ${tool} on ${filePath}: secrets files are off-limits. ` +
        "Ask the user for the value you need instead."
    );
    process.exit(2); // 2 = block the call and send stderr to Claude
  }

  process.exit(0);
});

