"""Portfolio MCP server (output of the Introduction to MCP course).

It exposes two tools to Claude Code over stdio.
The server is registered in .mcp.json under the name 'portfolio'.
"""
import os
import re
from pathlib import Path

from mcp.server.fastmcp import FastMCP

ROOT = Path(os.environ.get("PORTFOLIO_ROOT", ".")).resolve()
mcp = FastMCP("portfolio")

# Files the checkpoint expects; the paths match the README table
REQUIRED = {
    "Hooks config": ".claude/settings.json",
    "Hook script": ".claude/hooks/protect-secrets.js",
    "Slash command": ".claude/commands/certify-check.md",
    "MCP config": ".mcp.json",
    "Claude CI workflow": ".github/workflows/claude.yml",
}


@mcp.tool()
def portfolio_checklist() -> dict[str, str]:
    """Return OK or MISSING for each file the Step 8 checkpoint needs."""
    return {
        name: "OK" if (ROOT / path).is_file() else f"MISSING ({path})"
        for name, path in REQUIRED.items()
    }


@mcp.tool()
def list_certificates() -> list[dict[str, str]]:
    """Read the certificates table from README.md and return its rows."""
    readme = (ROOT / "README.md").read_text(encoding="utf-8")
    rows = []
    for line in readme.splitlines():
        # Matches rows like: | Course | Status | Link |
        m = re.match(r"^\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|$", line)
        if m and m.group(1) not in ("Course", "---") and "Academy" not in line:
            course, status, link = m.groups()
            if course.startswith(("Claude", "Introduction", "Building")):
                rows.append({
                    "course": course,
                    "status": status,
                    "link": link,
                    "placeholder": str(link.startswith("<")),
                })
    return rows


if __name__ == "__main__":
    mcp.run()  # stdio transport by default

